import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {painters} painters paint an infinitely long picket fence. Their starting pickets are given, in order, by the array [starts]. Painter i (matching the i-th entry of [starts]) paints every d_i-th picket starting from that starting picket. We call the base-{base} integer with digits (d_1, d_2, ..., d_{painters}) written in the same order as [starts] paintable if (i) every picket is painted exactly once, and (ii) the least common multiple of the step sizes d_i is exactly {lcm_target}. What is the sum of all such paintable base-{base} integers?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We construct an instance based on a canonical exact covering system built from powers of two,
# then apply a uniform translation modulo 2^n. This yields a unique exact cover with moduli
# [2, 4, 8, ..., 2^n, 2^n] and residues [s+1, s+2, s+4, ..., s+2^{n-1}, s] modulo corresponding moduli,
# realized as the least positive representatives (with 0 represented as the modulus itself).
while True:
    n = rng.randint(3, 6)  # difficulty and size control
    painters = n + 1
    L = 1 << n
    s = rng.randrange(0, L)
    # Build starts in the canonical order j=1..n followed by the final class j=n+1.
    starts = []
    for j in range(1, n+1):
        mod = 1 << j
        r = (s + (1 << (j-1))) % mod
        if r == 0:
            r = mod
        starts.append(r)
    r_last = s % L
    if r_last == 0:
        r_last = L
    starts.append(r_last)
    # Ensure distinct starting positions to avoid degenerate descriptions.
    if len(set(starts)) != len(starts):
        continue  # resample s
    # Choose a base larger than any digit to avoid carry ambiguities.
    base = rng.randint(L + 3, L + 100)
    return {
        'painters': painters,
        'starts': starts,
        'lcm_target': L,
        'base': base
    }

    def verifier(assign):
# Validate assignment
try:
    painters = int(assign['painters'])
    starts = list(assign['starts'])
    L = int(assign['lcm_target'])
    base = int(assign['base'])
except Exception:
    # malformed assignment
    return (False, None)  # invalid input
# Basic checks
if painters < 4:
    # We require at least 4 painters for nontrivial exact-cover structure.
    return (False, None)
if len(starts) != painters:
    return (False, None)
if any((not isinstance(x, int)) or x <= 0 for x in starts):
    return (False, None)
if len(set(starts)) != len(starts):
    return (False, None)
# Painters structure: n = painters - 1, L should be 2^n
n = painters - 1
if L != (1 << n):
    return (False, None)
if base <= L + 1:
    # keep base sufficiently large to encode digits without ambiguity
    return (False, None)
# Recover the translation parameter s from the last entry, which must represent residue s modulo 2^n.
s_cand = starts[-1] % L
# Recompute expected starts given s_cand.
expected_starts = []
for j in range(1, n+1):
    mod = 1 << j
    r = (s_cand + (1 << (j-1))) % mod
    if r == 0:
        r = mod
    expected_starts.append(r)
r_last = s_cand % L
if r_last == 0:
    r_last = L
expected_starts.append(r_last)
if starts != expected_starts:
    # The instance must match the canonical pattern; otherwise, it's not the intended family.
    return (False, None)
# Construct the moduli (step sizes) corresponding to this exact covering system.
d_list = [1 << j for j in range(1, n+1)] + [L]
# Sanity check LCM equals L
import math
def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)
LCM = 1
for d in d_list:
    LCM = lcm(LCM, d)
if LCM != L:
    return (False, None)
# Verify exact cover across one full period [1..L]. Coverage repeats modulo L.
for x in range(1, L+1):
    cnt = 0
    for s_start, d in zip(starts, d_list):
        if (x - s_start) % d == 0:
            cnt += 1
    if cnt != 1:
        return (False, None)
# Compute the base-{base} encoded integer with digits d_i in the given order.
# Sum of all paintable integers: in this family and constraints, the solution is unique.
ans = 0
for idx, d in enumerate(d_list):
    power = painters - 1 - idx
    ans += d * (base ** power)
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

